    /**
     * Method to retrieve the Anomaly via AnomalyFetchOneSummary
     * @param 	summary AnomalyFetchOneSummary 
     * @return 	AnomalyFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Anomaly getAnomaly( AnomalyFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AnomalyFetchOneSummary arg cannot be null" );
    	
    	Anomaly entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Anomaly
        	// --------------------------------------
        	CompletableFuture<Anomaly> futureEntity = queryGateway.query(new FindAnomalyQuery( new LoadAnomalyFilter( summary.getAnomalyId() ) ), ResponseTypes.instanceOf(Anomaly.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Anomaly with id " + summary.getAnomalyId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


